/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// PaffH 14.11.25
/// </summary>
/// <param name = "_recIdDXBVEMailRequestHeader">RecId</param>
/// <param name = "_company">DataAreaId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestPerCompany</returns>
public static NDXBVEMailRequestPerCompany find(RecId _recIdDXBVEMailRequestHeader, DataAreaId _company, boolean _forUpdate = true)
{
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany;
    nDXBVEMailRequestPerCompany.selectForUpdate(_forUpdate);
    select firstonly nDXBVEMailRequestPerCompany
        where nDXBVEMailRequestPerCompany.NDXBVEMailRequestHeader == _recIdDXBVEMailRequestHeader
        && nDXBVEMailRequestPerCompany.Company == _company;
    return nDXBVEMailRequestPerCompany;
}

/// <summary>
/// PaffH 14.11.25
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestPerCompany</returns>
public static NDXBVEMailRequestPerCompany findRecId(RecId _recId, boolean _forUpdate = true)
{
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany;
    nDXBVEMailRequestPerCompany.selectForUpdate(_forUpdate);
    select firstonly nDXBVEMailRequestPerCompany
        where nDXBVEMailRequestPerCompany.Recid == _recId;
    return nDXBVEMailRequestPerCompany;
}

/// <summary>
/// PaffH 28.11.25
/// </summary>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestHeader</returns>
public NDXBVEMailRequestHeader nDXBVEMailRequestHeader(boolean _forUpdate = false)
{
    return NDXBVEMailRequestHeader::findFromRecId(this.NDXBVEMailRequestHeader, _forUpdate);
}

/// <summary>
/// PaffH 01.12.25
/// </summary>
/// <param name = "_kCS_KBVRequestTable">KCS_KBVRequestTable</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestPerCompany</returns>
public static NDXBVEMailRequestPerCompany findFromKCS_KBVRequestTable(KCS_KBVRequestTable _kCS_KBVRequestTable, boolean _forUpdate = true)
{
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany;
    nDXBVEMailRequestPerCompany.selectForUpdate(_forUpdate);
    select firstonly nDXBVEMailRequestPerCompany
        where nDXBVEMailRequestPerCompany.KCS_KBVRequestTable == _kCS_KBVRequestTable.RecId
        && nDXBVEMailRequestPerCompany.Company == _kCS_KBVRequestTable.DataAreaId;
    return nDXBVEMailRequestPerCompany;
}

/// <summary>
/// PaffH 14.11.25
/// </summary>
/// <param name = "_recIdDXBVEMailRequestHeader">RecId</param>
/// <param name = "_company">DataAreaId</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXBVEMailRequestPerCompany</returns>
public static NDXBVEMailRequestPerCompany findOrCreate(RecId _recIdDXBVEMailRequestHeader, DataAreaId _company, boolean _insert = true)
{
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::find(_recIdDXBVEMailRequestHeader, _company, true);
    if (!nDXBVEMailRequestPerCompany)
    {
        nDXBVEMailRequestPerCompany.NDXBVEMailRequestHeader = _recIdDXBVEMailRequestHeader;
        nDXBVEMailRequestPerCompany.Company = _company;
        if (_insert)
        {
            nDXBVEMailRequestPerCompany.insert();
        }
    }
    return nDXBVEMailRequestPerCompany;
}

/// <summary>
/// PaffH 17.11.25
/// </summary>
/// <param name = "_nDXBVEMailRequestLine">NDXBVEMailRequestLine</param>
public static void checkFromNDXBVEMailRequestLine(NDXBVEMailRequestLine _nDXBVEMailRequestLine)
{
    Query q = new Query();
    QueryRun qr;
    QueryBuildDataSource qbds;
    RecId recId;
    Counter counter;
    NDXBVEMailRequestLine nDXBVEMailRequestLine;
    NDXBVEMailRequestHeader nDXBVEMailRequestHeader = _nDXBVEMailRequestLine.nDXBVEMailRequestHeader();
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany;
    Set setChecked = new Set(Types::Int64);
    Set setExists = new Set(Types::Int64);

    if (FormDataUtil::isFormDataSource(_nDXBVEMailRequestLine))
    {
        Map map = new Map(Types::Int64, Types::Integer);
        FormDataSource fds = FormDataUtil::getFormDataSource(_nDXBVEMailRequestLine);
        nDXBVEMailRequestLine = fds.getFirst();
        while (nDXBVEMailRequestLine)
        {
            if (nDXBVEMailRequestLine.ItemId && nDXBVEMailRequestLine.Deactive == NoYes::No)
            {
                nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::findOrCreate(nDXBVEMailRequestHeader.RecId, nDXBVEMailRequestLine.ItemIdDataAreaId, true);
                if (map.exists(nDXBVEMailRequestPerCompany.RecId))
                {
                    counter = map.lookup(nDXBVEMailRequestPerCompany.RecId);
                    counter += 1;
                }
                else
                {
                    counter = 1;
                }
                map.insert(nDXBVEMailRequestPerCompany.RecId, counter);
            }
            nDXBVEMailRequestLine = fds.getNext();
        }
        MapEnumerator enumMap = map.getEnumerator();
        while (enumMap.moveNext())
        {
            recId = enumMap.currentKey();
            counter = enumMap.currentValue();
            nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::findRecId(recId, true);
            if ( nDXBVEMailRequestPerCompany.NumberOfPositionsRequested != counter)
            {
                nDXBVEMailRequestPerCompany.NumberOfPositionsRequested = counter;
                ttsbegin;
                nDXBVEMailRequestPerCompany.write();
                ttscommit;
            }
            setChecked.add(nDXBVEMailRequestPerCompany.RecId);
        }
    }
    else
    {
        q = new Query();
        qbds = q.addDataSource(tableNum(NDXBVEMailRequestLine));
        qbds.addRange(fieldNum(NDXBVEMailRequestLine, IdentifierGUID)).value(queryValue(nDXBVEMailRequestHeader.IdentifierGUID));
        qbds.addRange(fieldNum(NDXBVEMailRequestLine, ItemId)).value(SysQuery::valueNotEmptyString());
        qbds.addRange(fieldNum(NDXBVEMailRequestLine, Deactive)).value(queryValue(NoYes::No));
        qbds.addGroupByField(fieldNum(NDXBVEMailRequestLine, ItemIdDataAreaId));
        qbds.addSelectionField(fieldNum(NDXBVEMailRequestLine, RecId), SelectionField::Count);
        qr = new QueryRun(q);

        while (qr.next())
        {
            nDXBVEMailRequestLine = qr.get(tableNum(NDXBVEMailRequestLine));
            nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::findOrCreate(nDXBVEMailRequestHeader.RecId, nDXBVEMailRequestLine.ItemIdDataAreaId, false);
            if (nDXBVEMailRequestPerCompany.RecId == 0 ||
            nDXBVEMailRequestPerCompany.NumberOfPositionsRequested != int642int(nDXBVEMailRequestLine.RecId))
            {
                nDXBVEMailRequestPerCompany.NumberOfPositionsRequested = int642int(nDXBVEMailRequestLine.RecId);
                ttsbegin;
                nDXBVEMailRequestPerCompany.write();
                ttscommit;
            }
            setChecked.add(nDXBVEMailRequestPerCompany.RecId);
        }
    }

    q = new Query();
    qbds = q.addDataSource(tableNum(NDXBVEMailRequestPerCompany));
    qbds.addRange(fieldNum(NDXBVEMailRequestPerCompany, NDXBVEMailRequestHeader)).value(queryValue(nDXBVEMailRequestHeader.RecId));
    qr = new QueryRun(q);
    while (qr.next())
    {
        nDXBVEMailRequestPerCompany = qr.get(tableNum(NDXBVEMailRequestPerCompany));
        setExists.add(nDXBVEMailRequestPerCompany.RecId);
    }
    Set diff = Set::difference(setExists, setChecked);
    SetEnumerator enum = diff.getEnumerator();
    while (enum.moveNext())
    {
        recId = enum.current();
        nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::findRecId(recId, true);
        ttsbegin;
        nDXBVEMailRequestPerCompany.delete();
        ttscommit;
    }
}

/// <summary>
/// PaffH 01.12.25
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        if (this.KCS_KBVRequestTable)
        {
            NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompanyLocal;
            select firstonly nDXBVEMailRequestPerCompanyLocal
            where nDXBVEMailRequestPerCompanyLocal.KCS_KBVRequestTable == this.KCS_KBVRequestTable
                && nDXBVEMailRequestPerCompanyLocal.RecId != this.RecId;
            if (nDXBVEMailRequestPerCompanyLocal)
            {
                ret = false;
                Error(strFmt('Die Anfrage [%1] ist bereits der BV-E-Mail-Anfrage [%2] zugeordnet. Eine Mehrfachzuordnung ist nicht möglich.',
                    this.KCS_KBVRequestTable, nDXBVEMailRequestPerCompanyLocal.NDXBVEMailRequestHeader));
            }
        }
    }

    return ret;
}
